package ai.capri.app

import androidx.lifecycle.ViewModelProvider
import androidx.test.core.app.ActivityScenario
import androidx.test.platform.app.InstrumentationRegistry
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.security.MessageDigest

/** A host driver sends generated bytes through the actual HTTP/USB path into this isolated chat. */
class LargeUploadDeviceTest {
    @Test fun hundredMiBFileIsImportedIntactWithoutInlineContext() {
        val ins=InstrumentationRegistry.getInstrumentation();val context=ins.targetContext
        val scenario=ActivityScenario.launch(MainActivity::class.java)
        lateinit var vm:CapriModel;scenario.onActivity{vm=ViewModelProvider(it)[CapriModel::class.java]}
        val chat=Session(title="Large upload isolated fixture")
        val ready=File(context.cacheDir,"large-upload-ready.json");val complete=File(context.cacheDir,"large-upload-complete")
        complete.delete()
        try {
            ins.runOnMainSync{vm.sessions.add(chat);vm.persist()}
            ready.writeText(JSONObject().put("chat",chat.id).put("epoch",DebugWebBridge.epoch).toString())
            val deadline=System.currentTimeMillis()+180000
            while(!complete.exists()&&System.currentTimeMillis()<deadline)Thread.sleep(100)
            check(complete.exists()){ "Host upload driver did not finish." }
            val item=vm.inputAttachments.list(chat.id).single()
            assertEquals(100L*1024*1024,item.getLong("size"))
            assertEquals(0,item.optInt("width"))
            val expected=MessageDigest.getInstance("SHA-256");val block=ByteArray(1024*1024){31};repeat(100){expected.update(block)}
            assertEquals(expected.digest().joinToString(""){"%02x".format(it)},item.getString("sha256"))
            val file=vm.store.workspace.file(chat.id,item.getString("path"));assertEquals(item.getLong("size"),file.length())
            assertTrue(InputAttachments.manifest(listOf(item)).length<2048)
            assertEquals(chat.id,JSONObject(ready.readText()).getString("chat"))
        }finally{
            vm.inputAttachments.clear(chat.id)
            ins.runOnMainSync{vm.sessions.removeAll{it.id==chat.id};vm.persist()}
            RuntimeFiles.delete(vm.store.workspace.root(chat.id));ready.delete();complete.delete();scenario.close()
        }
    }
}
